import base64
import pathlib
import subprocess
import sys
import tempfile

subprocess.run(
    [
        sys.executable,
        "-m",
        "pip",
        "install",
        "-q",
        "qiskit",
        "qiskit-aer",
        "qiskit-algorithms",
        "qiskit-optimization",
        "numpy",
        "scipy",
        "pandas",
    ],
    check=True,
)

SOURCES_B64 = {'Day37/3-9.py': '', 'Day38/1-1.py': '', 'Day38/1-2.py': '', 'Day38/1-3.py': '', 'Day38/1-4.py': '', 'Day39/2-1.py': '', 'Day39/2-2.py': '', 'Day39/2-3.py': '', 'Day39/2-4.py': '', 'Day39/2-5.py': '', 'Day39/2-6.py': '', 'Day39/Project/1-1.py': '', 'Day39/Project/1-2.py': '', 'Day39/Project/netflix_titles.csv': ''}
EXECUTION_ORDER = ['Day37/3-9.py', 'Day38/1-1.py', 'Day38/1-2.py', 'Day38/1-3.py', 'Day38/1-4.py', 'Day39/2-1.py', 'Day39/2-2.py', 'Day39/2-3.py', 'Day39/2-4.py', 'Day39/2-5.py', 'Day39/2-6.py', 'Day39/Project/1-1.py', 'Day39/Project/1-2.py']

with tempfile.TemporaryDirectory(prefix="quantum-ml-day37-day39-") as tmp:
    root = pathlib.Path(tmp)
    for relative_path, payload in SOURCES_B64.items():
        destination = root / relative_path
        destination.parent.mkdir(parents=True, exist_ok=True)
        destination.write_bytes(base64.b64decode(payload))
    for relative_path in EXECUTION_ORDER:
        source_path = root / relative_path
        print(f"COLAB_SOURCE_START {relative_path}", flush=True)
        subprocess.run(
            [sys.executable, source_path.name],
            cwd=source_path.parent,
            check=True,
        )
        print(f"COLAB_SOURCE_OK {relative_path}", flush=True)

print("COLAB_DAY37_DAY39_SOURCE_EXECUTION_OK", flush=True)
